<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3'; import { Download, Gauge, ShieldCheck, Users, AlertTriangle } from '@lucide/vue'; import { reactive } from 'vue'; import MetricCard from '@/Components/Shared/MetricCard.vue'; import AnalyticsHeader from '@/components/Analytics/AnalyticsHeader.vue';
import AnalyticsFilterPanel from '@/components/Analytics/AnalyticsFilterPanel.vue'; import ShowSection from '@/Components/Show/ShowSection.vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
const props=defineProps<{filters:any;report:any}>();const filters=reactive({...props.filters});const apply=()=>router.get('/admin/analytics/downloads',filters,{preserveState:true,replace:true});const exportUrl=()=>'/admin/analytics/downloads/export?'+new URLSearchParams(Object.entries(filters).filter(([,v])=>v!==''&&v!=null) as [string,string][]).toString();
</script><template><Head title="Download and License Utilization Analytics"/><div class="analytics-report-page space-y-8 p-6"><AnalyticsHeader title="Download and License Utilization Analytics" description="Monitor download behavior, entitlement health, file demand, and license utilization."><template #actions><Button variant="outline" as-child><a :href="exportUrl()">Export CSV</a></Button></template></AnalyticsHeader>
<AnalyticsFilterPanel content-class="grid gap-4 lg:grid-cols-4 lg:items-end" @submit="apply"><div class="grid gap-2"><Label>Search</Label><Input v-model="filters.search" placeholder="License, customer, or key..."/></div><div class="grid gap-2"><Label>Status</Label><select v-model="filters.status" class="h-10 rounded-md border bg-background px-3 text-sm"><option value="">All statuses</option><option value="active">Active</option><option value="expired">Expired</option><option value="revoked">Revoked</option><option value="refunded">Refunded</option></select></div><div class="grid gap-2"><Label>Period</Label><select v-model="filters.period" class="h-10 rounded-md border bg-background px-3 text-sm"><option value="7_days">Last 7 days</option><option value="30_days">Last 30 days</option><option value="90_days">Last 90 days</option><option value="year_to_date">Year to date</option></select></div><Button type="submit">Apply filters</Button></AnalyticsFilterPanel>
<section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><MetricCard label="Licenses" :value="report.summary.licenses_measured"><template #icon><ShieldCheck class="h-5 w-5"/></template></MetricCard><MetricCard label="Downloads" :value="report.summary.downloads"><template #icon><Download class="h-5 w-5"/></template></MetricCard><MetricCard label="Unique downloaders" :value="report.summary.unique_downloaders"><template #icon><Users class="h-5 w-5"/></template></MetricCard><MetricCard label="Unused licenses" :value="report.summary.unused_licenses"><template #icon><AlertTriangle class="h-5 w-5"/></template></MetricCard><MetricCard label="Near limit" :value="report.summary.near_limit_licenses"><template #icon><AlertTriangle class="h-5 w-5"/></template></MetricCard><MetricCard label="Avg. utilization" :value="`${report.summary.average_utilization_percent}%`"><template #icon><Gauge class="h-5 w-5"/></template></MetricCard></section>
<ShowSection title="License utilization" description="License health and download activity during the selected period."><div class="overflow-x-auto rounded-lg border"><table class="w-full text-sm"><thead class="bg-muted/40 text-left"><tr><th class="p-3">License</th><th class="p-3">Customer</th><th class="p-3">Asset</th><th class="p-3">Status</th><th class="p-3">Used / limit</th><th class="p-3">Period downloads</th><th class="p-3">Utilization</th></tr></thead><tbody><tr v-for="row in report.licenses" :key="row.license_id" class="border-t"><td class="p-3 font-medium"><Link :href="`/admin/analytics/downloads/${row.license_id}?period=${filters.period}`" class="hover:underline">{{row.license_name}}</Link><div class="text-xs text-muted-foreground">{{row.license_key}}</div></td><td class="p-3">{{row.customer_email||'—'}}</td><td class="p-3">{{row.asset_title}}</td><td class="p-3 capitalize">{{row.status}}</td><td class="p-3">{{row.downloads_used}} / {{row.download_limit??'∞'}}</td><td class="p-3">{{row.period_downloads}}</td><td class="p-3">{{row.utilization_percent}}%</td></tr><tr v-if="!report.licenses.length"><td colspan="7" class="p-10 text-center text-muted-foreground">No licenses matched this report.</td></tr></tbody></table></div></ShowSection>
<div class="grid gap-6 xl:grid-cols-3"><ShowSection title="Unused purchased licenses"><div v-for="r in report.opportunities.unused" :key="r.license_id" class="border-b py-3"><div class="font-medium">{{r.asset_title}}</div><div class="text-sm text-muted-foreground">{{r.customer_email}} · {{r.license_name}}</div></div></ShowSection><ShowSection title="Approaching limits"><div v-for="r in report.opportunities.near_limit" :key="r.license_id" class="border-b py-3"><div class="font-medium">{{r.asset_title}}</div><div class="text-sm text-muted-foreground">{{r.downloads_used}} of {{r.download_limit}} downloads used</div></div></ShowSection><ShowSection title="File-format demand"><div v-for="r in report.formats" :key="r.label" class="flex justify-between border-b py-3"><span class="font-medium">{{r.label}}</span><span class="text-sm text-muted-foreground">{{r.downloads}} downloads</span></div></ShowSection></div></div></template>
